{"tool":"write","path":"reports/export.py","content":""""Reports CSV exporter. Implement export_csv to satisfy TASK.txt."""

import csv
import io


def export_csv(rows, columns):
    """Export mappings in column order as RFC 4180 CSV, including the header."""
    cols = list(columns)
    seen = set()
    for name in cols:
        if not isinstance(name, str):
            raise ValueError("column names must be strings: %r" % (name,))
        if name in seen:
            raise ValueError("duplicate column name: %r" % (name,))
        seen.add(name)

    buf = io.StringIO()
    writer = csv.writer(buf, lineterminator="\r\n")
    writer.writerow(cols)
    for row in rows:
        writer.writerow([
            "" if row.get(name) is None else str(row.get(name))
            for name in cols
        ])
    return buf.getvalue()
